(5121271, 746203, 94855, '<td valign="top">I just don''t get it</td>', 'I just don''t get it', '2008-12-10 01:22:56.000000', NULL, 1),
(5121321, 746094, 100393, '<td valign="top">Given the number of water droplet photos on offer, it is difficult to filter them all out and look at this picture on its own merits. Of course it is very good indeed but will it get the score the picture deserves in the context of the brief for this challenge?</td>', 'Given the number of water droplet photos on offer, it is difficult to filter them all out and look at this picture on its own merits. Of course it is very good indeed but will it get the score the picture deserves in the context of the brief for this challenge?', '2008-12-10 01:54:59.000000', NULL, 1),
(5121326, 745357, 100393, '<td valign="top">I quite like this photo - the colours give a rustic feel. I can see the front edge of the plate and the bowl to the right is in focus. I would have perhaps aimed for the parsley sprig to be in focus and extended the depth of field a little.<br/> <br/>Nice though.</td>', 'I quite like this photo - the colours give a rustic feel. I can see the front edge of the plate and the bowl to the right is in focus. I would have perhaps aimed for the parsley sprig to be in focus and extended the depth of field a little. Nice though.', '2008-12-10 01:58:04.000000', NULL, 1),
(5121328, 746136, 96751, '<td valign="top">Great concept, but the execution (esp. the lighting) needs a little work.</td>', 'Great concept, but the execution (esp. the lighting) needs a little work.', '2008-12-10 01:58:42.000000', NULL, 1),
(5121331, 745438, 58667, '<td valign="top">This is great! I would just change one thing... I would flip the image to get before and after, not after and before. :o) (Unless of course before and after aging, but the title suggests otherwise)</td>', 'This is great! I would just change one thing... I would flip the image to get before and after, not after and before. :o) (Unless of course before and after aging, but the title suggests otherwise)', '2008-12-10 01:59:36.000000', NULL, 1),
(5121336, 745351, 100393, '<td valign="top">Great idea - I can see why you have used a narrow DOF but I think I would have aimed to try and get the whole of the front of the upper sandwich front edge in focus.</td>', 'Great idea - I can see why you have used a narrow DOF but I think I would have aimed to try and get the whole of the front of the upper sandwich front edge in focus.', '2008-12-10 02:01:41.000000', NULL, 1),
(5121337, 745545, 96751, '<td valign="top">I get the idea, but there''s something kinda forced about this. Also, lots of noise.</td>', 'I get the idea, but there''s something kinda forced about this. Also, lots of noise.', '2008-12-10 02:02:21.000000', NULL, 1),
(5121338, 745835, 96751, '<td valign="top">Nice and simple.  Clean image. Love it, and the detail, especially the dried leaf.</td>', 'Nice and simple.  Clean image. Love it, and the detail, especially the dried leaf.', '2008-12-10 02:02:53.000000', NULL, 1),
(5121339, 746013, 100393, '<td valign="top">Great photo - good idea, very well executed - perfect lighting and the crop is bang on.</td>', 'Great photo - good idea, very well executed - perfect lighting and the crop is bang on.', '2008-12-10 02:03:00.000000', NULL, 1),
(5121342, 746092, 100393, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2008-12-10 02:04:00.000000', NULL, 1),
(5121343, 745565, 96751, '<td valign="top">LOL!  Merry Crushmas!!  It''s just a tad too dark for me.  And the background X is a bit distracting.</td>', 'LOL!  Merry Crushmas!!  It''s just a tad too dark for me.  And the background X is a bit distracting.', '2008-12-10 02:04:06.000000', NULL, 1),
(5121345, 746100, 96751, '<td valign="top">Awesome concept incorporating the shadow.  In an advanced editing situation, it would have been a stronger image without the second (left) shadow.</td>', 'Awesome concept incorporating the shadow.  In an advanced editing situation, it would have been a stronger image without the second (left) shadow.', '2008-12-10 02:05:25.000000', NULL, 1),
(5121346, 745689, 100393, '<td valign="top">LOL - and with style!</td>', 'LOL - and with style!', '2008-12-10 02:05:27.000000', NULL, 1),
(5121349, 745918, 100393, '<td valign="top">Im imagine this will do very well!</td>', 'Im imagine this will do very well!', '2008-12-10 02:06:24.000000', NULL, 1),
(5121350, 745357, 96751, '<td valign="top">This image is too busy for me.  Feels like I need to use all the ingredients to figure out the final recipe.  I think it might have worked with just the potatoes and masher.  Also, I wish the image was a bit crisper.</td>', 'This image is too busy for me.  Feels like I need to use all the ingredients to figure out the final recipe.  I think it might have worked with just the potatoes and masher.  Also, I wish the image was a bit crisper.', '2008-12-10 02:07:00.000000', NULL, 1),
(5121351, 745949, 96751, '<td valign="top">Although a beautiful image, it doesn''t meet the challenge for me.</td>', 'Although a beautiful image, it doesn''t meet the challenge for me.', '2008-12-10 02:07:29.000000', NULL, 1),
(5121352, 746104, 100393, '<td valign="top">The title is very good and so is the image! Good job.</td>', 'The title is very good and so is the image! Good job.', '2008-12-10 02:07:37.000000', NULL, 1),
(5121354, 745956, 96751, '<td valign="top">Yummmmmmm.  Nice and crisp.</td>', 'Yummmmmmm.  Nice and crisp.', '2008-12-10 02:07:56.000000', NULL, 1),
