(5125760, 745914, 67237, '<td valign="top">excellent composition and dof here, with a concept that does fit the challenge..8</td>', 'excellent composition and dof here, with a concept that does fit the challenge..8', '2008-12-11 19:20:27.000000', NULL, 1),
(5125763, 746004, 67237, '<td valign="top">nice rembrandt light in dad''s face, a little harsh on the boy though..7</td>', 'nice rembrandt light in dad''s face, a little harsh on the boy though..7', '2008-12-11 19:22:24.000000', NULL, 1),
