(5126303, 746218, 37252, '<td valign="top">Cute humorous shot. I like it. The colors are pleasing, and the lighting well executed....as is the egg. :P</td>', 'Cute humorous shot. I like it. The colors are pleasing, and the lighting well executed....as is the egg. :P', '2008-12-12 02:34:55.000000', NULL, 1),
(5126304, 745722, 37252, '<td valign="top">Loved the music, but have never tried the wine. Well done on composition.</td>', 'Loved the music, but have never tried the wine. Well done on composition.', '2008-12-12 02:37:40.000000', NULL, 1),
(5126305, 746153, 37252, '<td valign="top">This seems a bit busy to me, and the lighting too harsh. <br/>Suggestions: <br/>1. Light from an angle instead of straight down onto the plate as it really makes the whites harsh.<br/>2. Use a solid color plate instead of one with distracting patterns.<br/>3. Consider displaying the raw eggs in a more appealing way than in the store carton.</td>', 'This seems a bit busy to me, and the lighting too harsh. Suggestions: 1. Light from an angle instead of straight down onto the plate as it really makes the whites harsh.2. Use a solid color plate instead of one with distracting patterns.3. Consider displaying the raw eggs in a more appealing way than in the store carton.', '2008-12-12 02:41:00.000000', NULL, 1),
(5126308, 745547, 37252, '<td valign="top">I like the way the sail boats pull me through the image. The little speed boat seems out of place though.</td>', 'I like the way the sail boats pull me through the image. The little speed boat seems out of place though.', '2008-12-12 02:43:36.000000', NULL, 1),
(5126309, 746096, 37252, '<td valign="top">Quite bright - not sure if  your shot this intentionally for high key, or edited it that way as you were trying different things. Either way it worked out.</td>', 'Quite bright - not sure if  your shot this intentionally for high key, or edited it that way as you were trying different things. Either way it worked out.', '2008-12-12 02:45:13.000000', NULL, 1),
